import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.abs

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()

    if (n == 2L) {
        println("white")
        println("1 2")
        return
    }

    if (n % 2L == 1L) {
        println("black")
        return
    }

    // n is even and >= 4
    println("white")

    // Candidate 1: (1, n/2)
    val r1 = 1L
    val c1 = n / 2L
    val d1 = abs(r1 - 1L) + abs(c1 - n)

    // Candidate 2: (2, n/2)
    val r2 = 2L
    val c2 = n / 2L
    val d2 = abs(r2 - 1L) + abs(c2 - n)

    if (d1 <= d2) {
        println("$r1 $c1")
    } else {
        println("$r2 $c2")
    }
}

